uint256 public limit;
function setLimit(uint256 next) external {
    require(next > 0, "zero limit");
    limit = next;
}

pragma solidity ^0.8.20;
contract PhaseBoard {
    enum Stage { Draft, Review, Published }
    Stage public stage;
    function publish() external { stage = Stage.Published; }
}
